-- ═══════════════════════════════════════════════════════════════
--  시연용 — 상품 사진을 실제 옷 사진으로 바꾸고, 도매처 10곳 · 상품 690건을 더한다
--
--  사진은 공개 데이터셋 benitomartin/fashion-product-images-small-384x512 에서
--  품목 · 성별 · 색 묶음마다 최대 6장을 골라 S3 listings/photos/ 아래에 둔
--  공용 사진첩(1605장)이다. 상품끼리 같은 사진을 돌려쓴다.
--  색상옵션의 색과 사진 색을 맞춰 골랐다. 그 색 사진이 없으면 가까운 색으로 물러선다.
--
--  1) V900 · V903 의 이미지 770장 주소를 사진첩으로 바꾼다 (게시글 · 순서가 같은 행)
--  2) 도매처 111~120 · 상품 690건 · 옵션 5310개 · 이미지 1688장을 더한다 — 합계 상품 약 1,000건
--
--  id 는 V903 다음 자리를 넉넉히 띄워 쓴다 — 상품 1500~ · 게시글 2500~ · 색상옵션 5000~ · 옵션 6000~ · 이미지 7000~
--  ⚠️ 개발 환경 전용(db/seed). 운영에는 안 들어간다.
-- ═══════════════════════════════════════════════════════════════

